CREATE TRIGGER RefDamage_Version_Create
	ON RefDamage
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RFM_PK, 'RFM'
	FROM inserted
GO
CREATE TRIGGER RefDamage_Version_Update
	ON RefDamage
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RFM_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefDamage_DataChangeHistory
	ON RefDamage
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RFM_PK, 'RFM' FROM inserted
	UNION
	SELECT RFM_PK, 'RFM' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefDamage_DataProcessingResult_Delete
	ON RefDamage
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RFM_PK
	END
GO
